课后习题：
auto numerals_view = split_result |
        std::views::transform([](auto v)
        {
            int value = 0;
            const char* begin = std::to_address(v.begin());
            const char* end   = std::to_address(v.end());

            const auto res = std::from_chars(begin, end, value);

            const bool ok = (res.ec == std::errc{}) &amp;&amp; (res.ptr == end);
            if (!ok)
            {
                throw std::runtime_error(&quot;Invalid numeric token&quot;);
            }
            return value;
        });
#ifdef __cpp_lib_ranges_to_container
    auto numerals =
        numerals_view | std::ranges::to&lt;std::vector&gt;();
#else
    std::vector&lt;int&gt; numerals;
    std::ranges::copy(numerals_view, std::back_inserter(numerals));
#endif
    std::cout &lt;&lt; numerals &lt;&lt; &#39;\n&#39;;
